const { Pool } = require('pg');

// Global connection pool
let pool;

// Function to create and configure connection pool
function createPool() {
  if (!pool) {
    pool = new Pool({
      connectionString: process.env.DATABASE_URL,
      ssl: false, // Set to true if your PostgreSQL server requires SSL
      max: 20, // Maximum number of clients in the pool
      idleTimeoutMillis: 30000, // Close idle clients after 30 seconds
      connectionTimeoutMillis: 2000, // Return an error after 2 seconds if connection cannot be established
    });

    // Handle pool errors
    pool.on('error', (err, client) => {
      console.error('Unexpected error on idle client', err);
      process.exit(-1);
    });
  }
  return pool;
}

// Get a client from the pool
async function getClient() {
  const pool = createPool();
  return await pool.connect();
}

// Execute a query with the pool
async function query(text, params) {
  const pool = createPool();
  const start = Date.now();

  try {
    const res = await pool.query(text, params);
    const duration = Date.now() - start;

    // Log query for debugging (remove in production)
    if (process.env.NODE_ENV === 'development') {
      console.log('Executed query', { text: text.substring(0, 100) + '...', duration, rows: res.rowCount });
    }

    return res;
  } catch (error) {
    console.error('Database query error:', error);
    throw error;
  }
}

// Close the pool (usually called when the application shuts down)
async function closePool() {
  if (pool) {
    await pool.end();
    pool = null;
  }
}

// Test database connection
async function testConnection() {
  try {
    const result = await query('SELECT NOW()');
    console.log('Database connection successful:', result.rows[0]);
    return true;
  } catch (error) {
    console.error('Database connection failed:', error);
    return false;
  }
}

// Execute schema setup
async function setupDatabase() {
  try {
    // Check if tables exist
    const result = await query(`
      SELECT table_name 
      FROM information_schema.tables 
      WHERE table_schema = 'public' 
      AND table_name = 'employees'
    `);

    if (result.rows.length === 0) {
      console.log('Database tables not found. Please run the schema setup first.');
      return false;
    }

    console.log('Database schema is already set up.');
    return true;
  } catch (error) {
    console.error('Error checking database schema:', error);
    return false;
  }
}

module.exports = {
  getClient,
  query,
  closePool,
  testConnection,
  setupDatabase
};

