import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { FiArrowLeft, FiSave, FiPlus, FiX } from 'react-icons/fi';
import { toast } from 'react-toastify';
import { Button } from '../../../components/Button';
import { Input } from '../../../components/Input';
import { Select } from '../../../components/Select';
import { Label } from '../../../components/Label';
import { Card } from '../../../components/Card';
import { Avatar } from '../../../components/Avatar';

export default function EditDepartment({ department, employees, teamLeads: initialTeamLeads, teamLeadIds: initialTeamLeadIds }) {
  const [formData, setFormData] = useState({
    name: department.name,
    teamLeadIds: initialTeamLeadIds
  });
  const [originalData, setOriginalData] = useState(department);
  const [errors, setErrors] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [teamLeads, setTeamLeads] = useState(initialTeamLeads);
  const [loading, setLoading] = useState(false);
  const router = useRouter();
  const { id } = router.query;

  const validateForm = () => {
    const newErrors = {};

    if (!formData.name.trim()) {
      newErrors.name = 'Department name is required';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));

    // Clear error when field is edited
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: undefined }));
    }
  };

  const handleAddTeamLead = (e) => {
    const leadId = e.target.value;
    if (!leadId) return;

    // Check if already in the list
    if (formData.teamLeadIds.includes(leadId)) {
      toast.info('This employee is already a team lead for this department');
      return;
    }

    setFormData(prev => ({
      ...prev,
      teamLeadIds: [...prev.teamLeadIds, leadId]
    }));

    // Update team leads display list
    const employee = employees.find(emp => emp.id === leadId);
    if (employee) {
      setTeamLeads(prev => [...prev, employee]);
    }

    // Reset select
    e.target.value = '';
  };

  const handleRemoveTeamLead = (leadId) => {
    setFormData(prev => ({
      ...prev,
      teamLeadIds: prev.teamLeadIds.filter(id => id !== leadId)
    }));

    setTeamLeads(prev => prev.filter(lead => lead.id !== leadId));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!validateForm()) return;

    setIsSubmitting(true);
    try {
      const response = await fetch(`/api/departments/${id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(formData),
      });

      if (response.ok) {
        const updatedDepartment = await response.json();
        toast.success(`Department "${updatedDepartment.name}" has been updated`);
        router.push(`/departments/${id}`);
      } else {
        const error = await response.json();
        throw new Error(error.message || 'Failed to update department');
      }
    } catch (error) {
      console.error('Failed to update department:', error);
      toast.error('Failed to update department');
    } finally {
      setIsSubmitting(false);
    }
  };

  if (loading) {
    return (
      <div className="flex justify-center items-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-primary-600"></div>
      </div>
    );
  }

  return (
    <div className="max-w-2xl mx-auto fade-in">
      <div className="mb-6">
        <Button
          variant="ghost"
          size="sm"
          onClick={() => router.push(`/departments/${id}`)}
          className="mb-2"
        >
          <FiArrowLeft className="mr-2" />
          Back to Department
        </Button>
        <h1 className="text-2xl font-bold">Edit Department</h1>
      </div>

      <Card>
        <form onSubmit={handleSubmit}>
          <Card.Content className="space-y-6">
            <div className="space-y-2">
              <Label htmlFor="name">
                Department Name <span className="text-red-500">*</span>
              </Label>
              <Input
                id="name"
                name="name"
                value={formData.name}
                onChange={handleChange}
                placeholder="e.g. Engineering, Marketing, HR"
                className={errors.name ? 'border-red-500' : ''}
              />
              {errors.name && (
                <p className="text-red-500 text-sm mt-1">{errors.name}</p>
              )}
            </div>

            <div className="space-y-2">
              <Label htmlFor="teamLeads">Team Leads</Label>
              <Select
                id="teamLeads"
                onChange={handleAddTeamLead}
                defaultValue=""
              >
                <option value="">-- Select Team Lead to Add --</option>
                {employees.map(emp => (
                  <option 
                    key={emp.id} 
                    value={emp.id}
                    disabled={formData.teamLeadIds.includes(emp.id)}
                  >
                    {emp.name} - {emp.designation}
                  </option>
                ))}
              </Select>

              <div className="mt-4">
                <Label>Current Team Leads</Label>
                {teamLeads.length === 0 ? (
                  <p className="text-sm text-gray-500 mt-2">No team leads assigned to this department.</p>
                ) : (
                  <div className="space-y-2 mt-2">
                    {teamLeads.map(lead => (
                      <div key={lead.id} className="flex items-center justify-between p-2 bg-gray-50 rounded-md">
                        <div className="flex items-center">
                          <Avatar 
                            fallback={lead.name} 
                            size="sm" 
                            className="mr-2"
                          />
                          <span>{lead.name}</span>
                        </div>
                        <Button 
                          variant="ghost" 
                          size="sm" 
                          onClick={() => handleRemoveTeamLead(lead.id)}
                          className="text-red-500 hover:text-red-700 hover:bg-red-50 h-8 w-8 p-0"
                        >
                          <FiX className="h-4 w-4" />
                        </Button>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </div>
          </Card.Content>

          <Card.Footer className="flex justify-end space-x-2 border-t pt-6">
            <Button
              type="button"
              variant="outline"
              onClick={() => router.push(`/departments/${id}`)}
              disabled={isSubmitting}
            >
              Cancel
            </Button>
            <Button
              type="submit"
              disabled={isSubmitting}
              className="flex items-center"
            >
              <FiSave className="mr-2" />
              {isSubmitting ? 'Saving...' : 'Save Changes'}
            </Button>
          </Card.Footer>
        </form>
      </Card>
    </div>
  );
}

