require('dotenv').config({ path: '.env.local' });

import { getEmployees, addEmployee } from '../../../lib/data';

export default async function handler(req, res) {
  if (req.method === 'GET') {
    try {
      console.log('API: Fetching employees...');
      console.log('DATABASE_URL exists:', !!process.env.DATABASE_URL);
      const employees = await getEmployees();
      console.log('API: Employees fetched:', employees.length);
      res.status(200).json(employees);
    } catch (error) {
      console.error('API Error fetching employees:', error);
      res.status(500).json({ error: 'Failed to fetch employees', details: error.message });
    }
  } else if (req.method === 'POST') {
    try {
      console.log('API: Creating employee...');
      const employeeData = req.body;

      // Validate required fields
      if (!employeeData.name || !employeeData.email) {
        return res.status(400).json({ error: 'Name and email are required' });
      }

      // Check if employee with same email already exists
      const existingEmployees = await getEmployees();
      const duplicateEmail = existingEmployees.find(emp => emp.email.toLowerCase() === employeeData.email.toLowerCase());

      if (duplicateEmail) {
        return res.status(400).json({ error: 'An employee with this email already exists' });
      }

      const newEmployee = await addEmployee(employeeData);
      console.log('API: Employee created:', newEmployee.id);
      res.status(201).json(newEmployee);
    } catch (error) {
      console.error('Error creating employee:', error);

      // Check for PostgreSQL unique constraint violation
      if (error.code === '23505') {
        return res.status(400).json({ error: 'An employee with this email already exists' });
      }

      res.status(500).json({ error: 'Failed to create employee' });
    }
  } else {
    res.setHeader('Allow', ['GET', 'POST']);
    res.status(405).end(`Method ${req.method} Not Allowed`);
  }
}

