  const { 
    getProjectById, 
    getProjectManagers
  } = require('../../../lib/data');
  const { id } = context.params;

  try {
    const [projectData, pmData] = await Promise.all([
      getProjectById(id),
      getProjectManagers()
    ]);

    if (!projectData) {
      return {
        notFound: true
      };
    }

    // Serialize dates
    const serializedProject = {
      ...projectData,
      created_at: projectData.created_at ? projectData.created_at.toISOString() : null,
      updated_at: projectData.updated_at ? projectData.updated_at.toISOString() : null
    };

    const serializedProjectManagers = pmData.map(pm => ({
      ...pm,
      created_at: pm.created_at ? pm.created_at.toISOString() : null,
      updated_at: pm.updated_at ? pm.updated_at.toISOString() : null
    }));

    return {
      props: {
        project: serializedProject,
        projectManagers: serializedProjectManagers
      }
    };
  } catch (error) {
    console.error('Error fetching project data:', error);
    return {
      notFound: true
    };
  }
