  return true;
};

export const login = async (email, password) => {
  console.log('Login attempt:', { email, password });

  // Check if credentials match admin credentials
  if (email === ADMIN_EMAIL && password === ADMIN_PASSWORD) {
    console.log('Admin login successful');
    const admin = { id: "admin-1", email: ADMIN_EMAIL, role: "admin" };
    Cookies.set('user', JSON.stringify(admin), { expires: 1 }); // 1 day
    return true;
  } else if (password === 'otp-verified') {
    console.log('OTP-verified login attempt');

    // For OTP-verified users, we'll determine their role on the server side
    // For now, create a basic employee user and let server-side logic handle role assignment
    const user = { 
      id: "user-" + Math.random().toString(36).substr(2, 9), 
      email, 
      role: "employee" 
    };
    console.log('Setting user cookie:', user);
    Cookies.set('user', JSON.stringify(user), { expires: 1 }); // 1 day
    return true;
  }

  console.log('Login failed');
  return false;
};

export const logout = () => {
  console.log('Logging out user');
  Cookies.remove('user');
};

export const getUser = () => {
  const userCookie = Cookies.get('user');
  if (!userCookie) {
    console.log('No user cookie found');
    return null;
  }
  try {
    const user = JSON.parse(userCookie);
    console.log('Retrieved user:', user);
    return user;
  } catch (error) {
    console.error('Error parsing user cookie:', error);
    return null;
  }
};

