// Higher-order function to wrap getServerSideProps with authentication
export const withAuth = (gssp) => {
  return async (context) => {
    // This runs on the server, so we can safely import data functions
    const { isAuthenticated, getUser } = require('./auth');

    // Check authentication
    if (!isAuthenticated()) {
      return {
        redirect: {
          destination: '/login',
          permanent: false,
        },
      };
    }

    // Call the original getServerSideProps
    return await gssp(context);
  };
};

